<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $holds = \App\Models\StockHold::where("stock_hold_voucher_id", 19)->get(); foreach($holds as $item) { if($item->warehouse_id == 0) { $p = \App\Models\Product::find($item->product_id); $p->stock += $item->hold_qty; $p->save(); } else { $s = \App\Models\WarehouseStock::firstOrNew(["warehouse_id" => $item->warehouse_id, "product_id" => $item->product_id]); $s->quantity = ($s->quantity ?? 0) + $item->hold_qty; if(!$s->exists) $s->status="Posted"; $s->save(); } } echo "Done\n";
